import styled from "styled-components";

export const HeaderContainer = styled.header`
    width: 100%;
    display: flex;
    justify-content: space-between;
    
    div{
        width:5rem;
        height:5rem;
       
    }
    div>img{
        width:100%;
        height: 5rem;
        object-fit: contain;
       
    }

`
